const BRAND = "#D93223";
const BRAND_DARK = "#B8281C";
const ORANGE = "#E67E22";
const BLUE = "#5B9BD5";

// Light theme
const L_INK = "#2A2A2A";
const L_BODY = "#3A3A3A";
const L_MUTED = "#6B6B6B";
const L_BORDER = "#E6E2DC";
const L_PAGE = "#F3F1EC";
const L_SHELL = "#FFFFFF";
const L_CARD = "#F7F5F1";
const L_ICON = "#FDECEA";
const WHITE = "#FFFFFE";

// Dark theme (concept photo 3)
const D_INK = "#F5F5F5";
const D_BODY = "#D8D8D8";
const D_MUTED = "#A0A0A0";
const D_BORDER = "#3A3A3A";
const D_PAGE = "#1A1A1A";
const D_SHELL = "#2A2A2A";
const D_CARD = "#242424";
const D_ICON = "#3A2A28";

const IMP = "!important";
const ASSET_VERSION = "20260725a";
const FONT_STACK = "'Oswald', Arial, Helvetica, sans-serif";
const FONT_LINK =
  "https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&display=swap";

const DISCLAIMER_HTML =
  "SLST is an internal operations tool for Swift Nisku warehouse staff. It helps us record what is staged, what is ready to ship, and what has left the building—and to notify sales when orders depart. It is not a carrier tracking system, proof-of-delivery tool, or comprehensive order-tracking platform. Expectations beyond this operational purpose fall outside the scope of the application.";

function bg(color: string): string {
  return `background-color:${color} ${IMP};`;
}

function fg(color: string): string {
  return `color:${color} ${IMP};`;
}

export function surfaceBg(color: string): string {
  return `${bg(color)} background-image:linear-gradient(${color},${color}) ${IMP};`;
}

/** Dual-theme CSS: light defaults + dark prefers-color-scheme / Outlook dark. */
export function themeCss(): string {
  const ctaGrad = `linear-gradient(${BRAND},${BRAND_DARK})`;
  return `
    :root, html { color-scheme: light dark ${IMP}; supported-color-schemes: light dark ${IMP}; }
    .logo-dark { display: none ${IMP}; max-height: 0 ${IMP}; overflow: hidden ${IMP}; }
    .logo-light { display: block ${IMP}; }
    @media (prefers-color-scheme: dark) {
      .og-page { ${bg(D_PAGE)} background-image:linear-gradient(${D_PAGE},${D_PAGE}) ${IMP}; }
      .og-shell, .og-footer { ${bg(D_SHELL)} background-image:linear-gradient(${D_SHELL},${D_SHELL}) ${IMP}; }
      .og-white, .og-card { ${bg(D_CARD)} background-image:linear-gradient(${D_CARD},${D_CARD}) ${IMP}; }
      .og-icon { ${bg(D_ICON)} background-image:linear-gradient(${D_ICON},${D_ICON}) ${IMP}; }
      .og-text, .og-text strong, .og-text h1 { ${fg(D_INK)} }
      .og-body { ${fg(D_BODY)} }
      .og-muted { ${fg(D_MUTED)} }
      .og-brand { ${fg(ORANGE)} }
      .og-border { border-color:${D_BORDER} ${IMP}; }
      .og-cta, .og-cta span {
        ${fg(WHITE)} border-color:${BRAND} ${IMP};
        ${bg(BRAND)} background-image:${ctaGrad} ${IMP};
      }
      .logo-light { display: none ${IMP}; max-height: 0 ${IMP}; overflow: hidden ${IMP}; width: 0 ${IMP}; height: 0 ${IMP}; }
      .logo-dark { display: block ${IMP}; max-height: none ${IMP}; overflow: visible ${IMP}; }
    }
    /* Outlook.com / Office dark-mode hooks */
    [data-ogsb] .og-page, [data-ogab] .og-page { ${bg(D_PAGE)} }
    [data-ogsb] .og-shell, [data-ogsb] .og-footer, [data-ogab] .og-shell { ${bg(D_SHELL)} }
    [data-ogsb] .og-white, [data-ogsb] .og-card, [data-ogab] .og-white { ${bg(D_CARD)} }
    [data-ogsc] .og-text, [data-ogac] .og-text { ${fg(D_INK)} }
    [data-ogsc] .og-body, [data-ogac] .og-body { ${fg(D_BODY)} }
    [data-ogsc] .og-muted, [data-ogac] .og-muted { ${fg(D_MUTED)} }
    [data-ogsc] .og-brand, [data-ogac] .og-brand { ${fg(ORANGE)} }
  `;
}

export function emailAssetUrl(fileKey: string, baseUrl?: string): string {
  const base = (baseUrl ?? DEFAULT_EMAIL_ASSET_BASE).replace(/\/$/, "");
  const key = fileKey.replace(/\.png$/i, "");
  if (base.includes("/functions/v1/email-assets")) {
    return `${base}?f=${encodeURIComponent(key)}&v=${ASSET_VERSION}`;
  }
  return `${base}/${encodeURIComponent(key)}.png?v=${ASSET_VERSION}`;
}

export function esc(value: string | undefined | null): string {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function displayOrNone(value: string | undefined | null): string {
  const v = String(value ?? "").trim();
  return v.length ? esc(v) : "None";
}

export function detailCard(opts: {
  iconUrl: string;
  title: string;
  accent: "orange" | "blue";
  rows: Array<{ label: string; value: string }>;
}): string {
  const accent = opts.accent === "blue" ? BLUE : ORANGE;
  const whiteSurf = surfaceBg(L_CARD);
  const iconSurf = surfaceBg(L_ICON);
  const rowsHtml = opts.rows
    .map(
      (r) => `
        <tr>
          <td class="og-text og-card" style="padding:0 0 10px 0;font-family:${FONT_STACK};font-size:14px;line-height:1.35;${whiteSurf}">
            <div class="og-text" style="font-weight:700;color:${L_INK};mso-line-height-rule:exactly;">
              ${esc(r.label)}
            </div>
            <div class="og-body" style="font-weight:400;padding-top:2px;color:${L_BODY};mso-line-height-rule:exactly;">
              ${r.value}
            </div>
          </td>
        </tr>`,
    )
    .join("");
  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="og-card og-border"
      style="${whiteSurf} border:2px solid ${L_BORDER};border-radius:14px;border-top:4px solid ${accent};box-shadow:0 4px 14px rgba(42,42,42,0.06);">
      <tr>
        <td class="og-card" style="padding:20px 18px 12px 18px;${whiteSurf}">
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
            <tr>
              <td width="44" valign="top" style="padding-right:12px;${whiteSurf}">
                <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="40" height="40" class="og-icon"
                  style="width:40px;height:40px;${iconSurf} border-radius:10px;">
                  <tr>
                    <td align="center" valign="middle" class="og-icon"
                      style="width:40px;height:40px;text-align:center;vertical-align:middle;${iconSurf}">
                      <img src="${esc(opts.iconUrl)}" width="24" height="24" alt=""
                        style="display:block;margin:0 auto;border:0;outline:none;-ms-interpolation-mode:bicubic;" />
                    </td>
                  </tr>
                </table>
              </td>
              <td valign="middle" class="og-brand" style="${whiteSurf}">
                <div class="og-brand" style="font-family:${FONT_STACK};font-size:12px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:${accent};mso-line-height-rule:exactly;">
                  ${esc(opts.title)}
                </div>
              </td>
            </tr>
          </table>
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin-top:14px;">
            ${rowsHtml}
          </table>
        </td>
      </tr>
    </table>`;
}

