function attachmentsSection(
  attachmentUrls: string[],
  assetBase: string,
): string {
  if (!attachmentUrls.length) return "";
  const cargo = emailAssetUrl("icon-cargo", assetBase);
  const gallery = attachmentUrls.slice(0, 8).map((url, i) => `
    <tr>
      <td style="padding:8px 0;">
        <a href="${esc(url)}" style="text-decoration:none;">
          <img src="${esc(url)}" width="520" alt="Attachment ${i + 1}"
            style="display:block;width:100%;max-width:520px;height:auto;border-radius:10px;border:2px solid ${L_BORDER};" />
        </a>
      </td>
    </tr>`).join("");
  return `
    <tr>
      <td class="og-shell" style="padding:0 22px 10px 22px;${surfaceBg(L_SHELL)}">
        ${detailCard({
          iconUrl: cargo,
          title: "ATTACHMENTS",
          accent: "orange",
          rows: [{
